import java.util.Scanner;

public class Main {
    static class InputParams {
        long mod;
        int n, m;

        boolean read(Scanner sc) {
            if (sc.hasNextInt()) {
                n = sc.nextInt();
                m = sc.nextInt();
                mod = sc.nextLong();
                return true;
            }
            return false;
        }
    }

    static class OutputResult extends InputParams {
        long result;

        void print() {
            System.out.println(result);
        }
    }

    static class Solver extends OutputResult {
        long[][] comb;
        Pair[] seq;
        Pair[][] dp;

        static class Pair {
            long first;
            long second;

            Pair(long first, long second) {
                this.first = first;
                this.second = second;
            }
        }

        long binpow(long base, long exp) {
            long res = 1;
            while (exp > 0) {
                if ((exp & 1) == 1) res = res * base % mod;
                base = base * base % mod;
                exp >>= 1;
            }
            return res;
        }

        long modInverse(long x) {
            return binpow(x, mod - 2);
        }

        void compute() {
            comb = new long[n + 1][n + 1];
            for (int i = 0; i <= n; ++i) {
                for (int j = 0; j <= n; ++j) {
                    if (i == 0 || j == 0) {
                        comb[i][j] = 1;
                    } else {
                        comb[i][j] = (comb[i - 1][j] + comb[i][j - 1]) % mod;
                    }
                }
            }

            seq = new Pair[m + 1];
            for (int i = 0; i <= m; ++i) {
                seq[i] = new Pair(0, 0);
            }
            seq[0] = new Pair(1, 0);

            for (int i = 1; i <= m; ++i) {
                for (int j = 0; j < i; ++j) {
                    Pair cur = new Pair(0, 0);
                    cur.first = seq[j].first * seq[i - 1 - j].first % mod;
                    cur.second = (seq[j].second * seq[i - 1 - j].first + seq[j].first * seq[i - 1 - j].second) % mod;
                    long ssSum = ss(j) + ss(i - 1 - j);
                    cur.second = (cur.second * (i + 1) + ssSum * cur.first) % mod;
                    cur.first = cur.first * (i + 1) % mod;
                    cur.first = cur.first * comb[j][i - 1 - j] % mod;
                    cur.second = cur.second * comb[j][i - 1 - j] % mod;
                    seq[i].first = (seq[i].first + cur.first) % mod;
                    seq[i].second = (seq[i].second + cur.second) % mod;
                }
            }

            dp = new Pair[n + 2][m + 1];
            for (int i = 0; i <= n + 1; ++i) {
                for (int j = 0; j <= m; ++j) {
                    dp[i][j] = new Pair(0, 0);
                }
            }
            dp[0][0] = new Pair(1, 0);

            for (int i = 0; i <= n + 1; ++i) {
                for (int j = 0; j <= m; ++j) {
                    for (int k = 0; k <= Math.min(n - i, m - j); ++k) {
                        Pair cur = new Pair(0, 0);
                        cur.first = seq[k].first * dp[i][j].first % mod;
                        cur.second = (seq[k].second * dp[i][j].first + seq[k].first * dp[i][j].second) % mod;
                        long c = comb[j][k];
                        cur.first = cur.first * c % mod;
                        cur.second = cur.second * c % mod;
                        int ni = i + k + 1;
                        int nj = j + k;
                        dp[ni][nj].first = (dp[ni][nj].first + cur.first) % mod;
                        dp[ni][nj].second = (dp[ni][nj].second + cur.second) % mod;
                    }
                }
            }
            result = dp[n + 1][m].second;
        }

        long ss(int x) {
            // Placeholder for ss function, assuming it's a sum or similar; since original code doesn't define ss,
            // we can assume ss(i) = i for simplicity, or implement as needed.
            return x;
        }

        void reset_state() {
            // Resetting the object state
            this.n = 0;
            this.m = 0;
            this.mod = 0;
            this.result = 0;
        }
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        InputParams inputParams = new InputParams();
        if (System.getenv("SG") != null) {
            // In Java, no direct equivalent of freopen, so assuming input is from stdin
            while (true) {
                if (!inputParams.read(sc)) break;
                Solver sol = new Solver();
                sol.n = inputParams.n;
                sol.m = inputParams.m;
                sol.mod = inputParams.mod;
                sol.compute();
                sol.print();
                sol.reset_state();
            }
        } else {
            if (inputParams.read(sc)) {
                Solver sol = new Solver();
                sol.n = inputParams.n;
                sol.m = inputParams.m;
                sol.mod = inputParams.mod;
                sol.compute();
                sol.print();
            }
        }
        sc.close();
    }
}
